script.script:
def build = Thread.currentThread().executable
def parameters = build.getAction(hudson.model.ParametersAction)
def rolloutRunId = parameters?.getParameter("BANNER_ROLLOUT_RUN_ID")?.value?.toString()
if (rolloutRunId) {
    def cause = build.getCause(hudson.model.Cause.UpstreamCause)
    if (cause == null || cause.upstreamProject != "PIC-SURE Pipeline Build and Deploy" || rolloutRunId != "combined-${cause.upstreamBuild}") {
        throw new hudson.AbortException("Banner artifact build requires its exact combined-pipeline upstream run")
    }
}
